def family_init(ctx):
    b = ctx.bars
    n = len(b)
    v = [float(x.get("v") or 0.0) for x in b]
    ctx.a = ctx.indicator("atr", period=int(ctx.p.atr_n))
    VN = int(ctx.p.vol_n)
    av = [None] * n
    s = 0.0
    for j in range(n):
        s += v[j]
        if j >= VN:
            s -= v[j - VN]
        if j >= VN - 1 and VN > 0:
            av[j] = s / VN
    ctx.av = ctx.series(av, "avgvol")


def signal(ctx, i):
    if i < 3:
        return 0
    a = ctx.a[i - 2]
    av = ctx.av[i - 2]
    if a is None or av is None or a <= 0 or av <= 0:
        return 0

    h1, l1, c1, v1 = ctx.h[i - 2], ctx.l[i - 2], ctx.c[i - 2], ctx.v[i - 2]
    r1 = h1 - l1
    if r1 <= 0:
        return 0
    # --- bar 1: the ignition. Wide, heavy, closing on its extreme.
    if r1 < float(ctx.p.ign_atr) * a:
        return 0
    if v1 < float(ctx.p.vol_mult) * av:
        return 0
    loc = (c1 - l1) / r1

    # --- bar 2: the hold. Narrow, quiet, and it gives almost nothing back.
    h2, l2, v2 = ctx.h[i - 1], ctx.l[i - 1], ctx.v[i - 1]
    r2 = h2 - l2
    if r2 > float(ctx.p.r2_cap) * r1:
        return 0
    if v1 > 0 and v2 > float(ctx.p.v2_cap) * v1:
        return 0
    keep = 1.0 - float(ctx.p.giveback)
    tick = float(ctx.p.tick)

    # --- bar 3: the release, taken only on the very next bar.
    if loc >= float(ctx.p.loc_min):
        if h2 <= h1 and l2 >= l1 + keep * r1 and ctx.h[i] > h2 + tick:
            return 1
    if loc <= 1.0 - float(ctx.p.loc_min):
        if l2 >= l1 and h2 <= h1 - keep * r1 and ctx.l[i] < l2 - tick:
            return -1
    return 0
